  CausalSmith.PartialID.SlateBenefitPartialTransport.WeakConverges Xn Q μ →
    have Qn := fun n => ⟨MeasureTheory.Measure.map (Xn n) μ, MeasureTheory.Measure.isProbabilityMeasure_map (Measurable.aemeasurable (hX n))⟩;
