∀ {𝒳 : Type uCell} [inst : Fintype 𝒳] [inst_1 : DecidableEq 𝒳] [inst_2 : MeasurableSpace 𝒳] [inst_3 : MeasurableSingletonClass 𝒳] {K : ℕ} {P : Causalean.PO.POSystem} (S : CausalSmith.PartialID.SlateBenefitPartialTransport.POSlateSystem P 𝒳 K) (T : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdCellTable 𝒳 K) (hp : ∀ (x : 𝒳), 0 ≤ S.p x) (hprop : ∀ (x : 𝒳), 0 ≤ S.propensity x ∧ S.propensity x ≤ 1) (hTnonnegative : T.Nonnegative) (hTnormalized : T.Normalized) (x : 𝒳),
  have W := CausalSmith.PartialID.SlateBenefitPartialTransport.canonicalThresholdCandidate S T hp hprop hTnonnegative hTnormalized;
  W.system.μ.real (W.slate.xEvent x) = S.p x

∀ {𝒳 : Type uCell} [inst : Fintype 𝒳] [inst_1 : DecidableEq 𝒳] [inst_2 : MeasurableSpace 𝒳] [inst_3 : MeasurableSingletonClass 𝒳] {K : ℕ} {P : Causalean.PO.POSystem} (S : CausalSmith.PartialID.SlateBenefitPartialTransport.POSlateSystem P 𝒳 K) (T : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdCellTable 𝒳 K) (hp : ∀ (x : 𝒳), 0 ≤ S.p x) (hprop : ∀ (x : 𝒳), 0 ≤ S.propensity x ∧ S.propensity x ≤ 1) (hTnonnegative : T.Nonnegative) (hTnormalized : T.Normalized),
  have W := CausalSmith.PartialID.SlateBenefitPartialTransport.canonicalThresholdCandidate S T hp hprop hTnonnegative hTnormalized;
  CausalSmith.PartialID.SlateBenefitPartialTransport.TreatmentConsistency W.slate ∧ CausalSmith.PartialID.SlateBenefitPartialTransport.SelectionExclusion W.slate ∧ CausalSmith.PartialID.SlateBenefitPartialTransport.OutcomeExclusion W.slate

∀ {𝒳 : Type uCell} [inst : Fintype 𝒳] [inst_1 : DecidableEq 𝒳] [inst_2 : MeasurableSpace 𝒳] [inst_3 : MeasurableSingletonClass 𝒳] {K : ℕ} {P : Causalean.PO.POSystem} (S : CausalSmith.PartialID.SlateBenefitPartialTransport.POSlateSystem P 𝒳 K) (T : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdCellTable 𝒳 K) (hp : ∀ (x : 𝒳), 0 ≤ S.p x) (hprop : ∀ (x : 𝒳), 0 ≤ S.propensity x ∧ S.propensity x ≤ 1) (hTnonnegative : T.Nonnegative) (hTnormalized : T.Normalized) (a : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdAtom 𝒳 K),
  have W := CausalSmith.PartialID.SlateBenefitPartialTransport.canonicalThresholdCandidate S T hp hprop hTnonnegative hTnormalized;
  W.system.μ.real {ω | W.slate.factualX ω = a.x ∧ W.slate.factualZ ω = a.z ∧ W.slate.D0 ω = a.d0 ∧ W.slate.D1 ω = a.d1 ∧ W.slate.S0 ω = a.s0 ∧ W.slate.S1 ω = a.s1 ∧ W.slate.Y0 ω = a.y0 ∧ W.slate.Y1 ω = a.y1} = CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdPastedWeight S T a

∀ {𝒳 : Type uCell} [inst : Fintype 𝒳] [inst_1 : DecidableEq 𝒳] [inst_2 : MeasurableSpace 𝒳] [inst_3 : MeasurableSingletonClass 𝒳] {K : ℕ} {P : Causalean.PO.POSystem} (S : CausalSmith.PartialID.SlateBenefitPartialTransport.POSlateSystem P 𝒳 K) (T : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdCellTable 𝒳 K) (hp : ∀ (x : 𝒳), 0 ≤ S.p x) (hprop : ∀ (x : 𝒳), 0 ≤ S.propensity x ∧ S.propensity x ≤ 1) (hTnonnegative : T.Nonnegative) (hTnormalized : T.Normalized),
  have W := CausalSmith.PartialID.SlateBenefitPartialTransport.canonicalThresholdCandidate S T hp hprop hTnonnegative hTnormalized;
  CausalSmith.PartialID.SlateBenefitPartialTransport.IVIndependence W.slate

∀ {𝒳 : Type uCell} [inst : Fintype 𝒳] [inst_1 : DecidableEq 𝒳] [inst_2 : MeasurableSpace 𝒳] [inst_3 : MeasurableSingletonClass 𝒳] {K : ℕ} {P : Causalean.PO.POSystem} (S : CausalSmith.PartialID.SlateBenefitPartialTransport.POSlateSystem P 𝒳 K) (T : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdCellTable 𝒳 K) (hp : ∀ (x : 𝒳), 0 ≤ S.p x) (hprop : ∀ (x : 𝒳), 0 ≤ S.propensity x ∧ S.propensity x ≤ 1) (hTnonnegative : T.Nonnegative) (hTnormalized : T.Normalized) (x : 𝒳) (d0 d1 s0 s1 : Bool) (y0 y1 : Fin K),
  have W := CausalSmith.PartialID.SlateBenefitPartialTransport.canonicalThresholdCandidate S T hp hprop hTnonnegative hTnormalized;
  W.system.μ.real {ω | W.slate.factualX ω = x ∧ W.slate.D0 ω = d0 ∧ W.slate.D1 ω = d1 ∧ W.slate.S0 ω = s0 ∧ W.slate.S1 ω = s1 ∧ W.slate.Y0 ω = y0 ∧ W.slate.Y1 ω = y1} = S.p x * T x d0 d1 s0 s1 y0 y1

∀ {𝒳 : Type uCell} [inst : Fintype 𝒳] [inst_1 : DecidableEq 𝒳] [inst_2 : MeasurableSpace 𝒳] [inst_3 : MeasurableSingletonClass 𝒳] {K : ℕ} {P : Causalean.PO.POSystem} (S : CausalSmith.PartialID.SlateBenefitPartialTransport.POSlateSystem P 𝒳 K) (T : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdCellTable 𝒳 K) (hp : ∀ (x : 𝒳), 0 ≤ S.p x) (hprop : ∀ (x : 𝒳), 0 ≤ S.propensity x ∧ S.propensity x ≤ 1) (hTnonnegative : T.Nonnegative) (hTnormalized : T.Normalized) (o : CausalSmith.PartialID.SlateBenefitPartialTransport.ObservedDatum 𝒳 K),
  have W := CausalSmith.PartialID.SlateBenefitPartialTransport.canonicalThresholdCandidate S T hp hprop hTnonnegative hTnormalized;
  W.slate.observedLaw.real {o} = ∑ a, if CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdObservedDatum a = o then CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdPastedWeight S T a else 0

∀ {𝒳 : Type uCell} [inst : Fintype 𝒳] [inst_1 : DecidableEq 𝒳] [inst_2 : MeasurableSpace 𝒳] [inst_3 : MeasurableSingletonClass 𝒳] {K : ℕ} {P : Causalean.PO.POSystem} (S : CausalSmith.PartialID.SlateBenefitPartialTransport.POSlateSystem P 𝒳 K) (T : CausalSmith.PartialID.SlateBenefitPartialTransport.ThresholdCellTable 𝒳 K) (hp : ∀ (x : 𝒳), 0 ≤ S.p x) (hprop : ∀ (x : 𝒳), 0 ≤ S.propensity x ∧ S.propensity x ≤ 1) (hTnonnegative : T.Nonnegative) (hTnormalized : T.Normalized) (x : 𝒳) (qz : Bool → Prop) [inst_4 : DecidablePred qz] (qL : Bool → Bool → Bool → Bool → Fin K → Fin K → Prop) [inst_5 : (d0 d1 s0 s1 : Bool) → (y0 y1 : Fin K) → Decidable (qL d0 d1 s0 s1 y0 y1)],
  have W := CausalSmith.PartialID.SlateBenefitPartialTransport.canonicalThresholdCandidate S T hp hprop hTnonnegative hTnormalized;
  W.system.μ.real {ω | W.slate.factualX ω = x ∧ qz (W.slate.factualZ ω) ∧ qL (W.slate.D0 ω) (W.slate.D1 ω) (W.slate.S0 ω) (W.slate.S1 ω) (W.slate.Y0 ω) (W.slate.Y1 ω)} = (S.p x * ∑ z, if qz z then CausalSmith.PartialID.SlateBenefitPartialTransport.atomInstrumentMass S x z else 0) * ∑ d0, ∑ d1, ∑ s0, ∑ s1, ∑ y0, ∑ y1, if qL d0 d1 s0 s1 y0 y1 then T x d0 d1 s0 s1 y0 y1 else 0

