  CausalSmith.PartialID.SlateBenefitPartialTransport.IVIndependence S →
    CausalSmith.PartialID.SlateBenefitPartialTransport.NoDefiers S →
      CausalSmith.PartialID.SlateBenefitPartialTransport.WeakSelectionMonotonicity S d →
        ∀ (compatible : CausalSmith.PartialID.SlateBenefitPartialTransport.TieSafeSurvivorModel S εZ d),
          let c := CausalSmith.PartialID.SlateBenefitPartialTransport.observableCapacities S.observedLaw;
          have hIdentification := CausalSmith.PartialID.SlateBenefitPartialTransport.capacity_identification S εZ d compatible.ivIndependence compatible.treatmentConsistency compatible.selectionExclusion compatible.outcomeExclusion compatible.instrumentOverlap compatible.noDefiers compatible.weakSelectionMonotonicity;
          have hValid := hIdentification.left.right;
          have hp := hIdentification.right.left;
          have hMass := compatible.positiveAggregateSurvivors;
          ∃ baseline,
            have flows := fun x => CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdFlow baseline hValid x;
            ∃ PL SL PU SU, CausalSmith.PartialID.SlateBenefitPartialTransport.IsEndpointWitness S.observedLaw εZ d (c.endpointMap S.p S.observedLaw rfl (CausalSmith.PartialID.SlateBenefitPartialTransport.p_eq_observedCellWeights S) hValid hp hMass (CausalSmith.PartialID.SlateBenefitPartialTransport.observedLawDomain S)).endpoints.1 PL SL ∧ CausalSmith.PartialID.SlateBenefitPartialTransport.IsEndpointWitness S.observedLaw εZ d (c.endpointMap S.p S.observedLaw rfl (CausalSmith.PartialID.SlateBenefitPartialTransport.p_eq_observedCellWeights S) hValid hp hMass (CausalSmith.PartialID.SlateBenefitPartialTransport.observedLawDomain S)).endpoints.2 PU SU ∧ (∀ (x : 𝒳), CausalSmith.PartialID.SlateBenefitPartialTransport.RealizesThresholdLatentCompletion { system := PL, slate := SL } x (flows x).lower) ∧ ∀ (x : 𝒳), CausalSmith.PartialID.SlateBenefitPartialTransport.RealizesThresholdLatentCompletion { system := PU, slate := SU } x (flows x).upper

