  let c := CausalSmith.PartialID.SlateBenefitPartialTransport.observableCapacities S.observedLaw;
  have hIdentification := CausalSmith.PartialID.SlateBenefitPartialTransport.capacity_identification S εZ d model.ivIndependence model.treatmentConsistency model.selectionExclusion model.outcomeExclusion model.instrumentOverlap model.noDefiers model.weakSelectionMonotonicity;
  have hValid := hIdentification.left.right;
  have hp := hIdentification.right.left;
  have hMass := model.positiveAggregateSurvivors;
  (∀ (x : 𝒳), 0 < S.p x → {γ | ∃ W, CausalSmith.PartialID.SlateBenefitPartialTransport.FullLawFeasible S.observedLaw W ∧ γ = CausalSmith.PartialID.SlateBenefitPartialTransport.fullLawSurvivorCoupling W x} = CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x) ∧
    (∀ (x : 𝒳), 0 < S.p x → (0 < c.gap x → CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x = CausalSmith.PartialID.SlateBenefitPartialTransport.incPolytope c hValid x) ∧ (c.gap x < 0 → CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x = CausalSmith.PartialID.SlateBenefitPartialTransport.decPolytope c hValid x) ∧ (c.gap x = 0 → CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x = CausalSmith.PartialID.SlateBenefitPartialTransport.tiePolytope c hValid x)) ∧
      (∀ (x : 𝒳), 0 < S.p x → sInf (CausalSmith.PartialID.SlateBenefitPartialTransport.benefitMass '' CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x) = c.benefitLower x ∧ sSup (CausalSmith.PartialID.SlateBenefitPartialTransport.benefitMass '' CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x) = c.benefitUpper x) ∧
        (∀ (x : 𝒳), c.mass x = 0 → CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x = {0}) ∧
          (Causalean.PartialID.IdentifiedInterval (fun W => CausalSmith.PartialID.SlateBenefitPartialTransport.benefitProbabilityOf W) fun W => CausalSmith.PartialID.SlateBenefitPartialTransport.FullLawFeasible S.observedLaw W) = c.identifiedIcc S.p S.observedLaw rfl (CausalSmith.PartialID.SlateBenefitPartialTransport.p_eq_observedCellWeights S) hValid hp hMass (CausalSmith.PartialID.SlateBenefitPartialTransport.observedLawDomain S) ∧
            ∀ (x : 𝒳), 0 < S.p x → CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdFlowLower c hValid x ∈ CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x ∧ CausalSmith.PartialID.SlateBenefitPartialTransport.benefitMass (CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdFlowLower c hValid x) = c.benefitLower x ∧ CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdFlowUpper c hValid x ∈ CausalSmith.PartialID.SlateBenefitPartialTransport.branchFreePolytope c hValid x ∧ CausalSmith.PartialID.SlateBenefitPartialTransport.benefitMass (CausalSmith.PartialID.SlateBenefitPartialTransport.thresholdFlowUpper c hValid x) = c.benefitUpper x

